56	    fn ack_configure(&mut self, surface: WlSurface, _configure: Configure) {
57	        // Smithay has already accepted this serial and retired its predecessors.
58	        // State requests can arrive before the first buffer. The helper's
59	        // initial_configure_sent check prevents a stale post-unmap ack from
60	        // starting the next mapping cycle prematurely.
61	        if let Some(item) = self.window_id(&surface).and_then(|id| self.windows.get(id))
62	            && let Some(toplevel) = item.window.toplevel()
63	        {
64	            crate::configure::send_pending(toplevel);
