69	    fn new_popup(&mut self, surface: PopupSurface, _positioner: PositionerState) {
70	        // Creating a fresh popup after its root left the scene must not recreate
71	        // a tree that was dismissed by an earlier unmap/hide transaction.
72	        let visible = find_popup_root_surface(&PopupKind::Xdg(surface.clone()))
73	            .is_ok_and(|root| self.popup_root_visible(&root));
74	        if !visible {
75	            surface.send_popup_done();
