185	    fn grab(&mut self, surface: PopupSurface, seat: wl_seat::WlSeat, serial: Serial) {
186	        self.cleanup_popup_grab();
187	        let Some(seat) = Seat::from_resource(&seat) else {
188	            surface.send_popup_done();
189	            return;
190	        };
191	        // Only an active same-client pointer press authorizes a new popup grab.
192	        // Keyboard/touch initiated grabs remain unsupported until their input
193	        // serial provenance is tracked explicitly.
194	        if !self
195	            .pointer_presses
196	            .values()
197	            .any(|pressed| *pressed == serial)
198	        {
199	            self.stats.popup_grabs_denied_missing_press = self
200	                .stats
201	                .popup_grabs_denied_missing_press
202	                .saturating_add(1);
203	            surface.send_popup_done();
204	            return;
205	        }
206	        if check_grab(&seat, surface.wl_surface(), serial).is_none() {
207	            surface.send_popup_done();
208	            return;
209	        }
210	        let kind = PopupKind::Xdg(surface.clone());
211	        let Ok(root) = find_popup_root_surface(&kind) else {
212	            surface.send_popup_done();
213	            return;
214	        };
215	        let Some(id) = self.window_id(&root) else {
216	            surface.send_popup_done();
217	            return;
218	        };
219	        if !self.popup_root_visible(&root) {
220	            surface.send_popup_done();
221	            return;
222	        }
223	        let Ok(mut grab) = self.popups.grab_popup(root, kind, &seat, serial) else {
224	            surface.send_popup_done();
225	            return;
226	        };
227	        self.popup_grab = Some((id, grab.clone()));
228	        if let Some(keyboard) = seat.get_keyboard() {
229	            if keyboard.is_grabbed()
230	                && !(keyboard.has_grab(serial)
231	                    || keyboard.has_grab(grab.previous_serial().unwrap_or(serial)))
232	            {
233	                grab.ungrab(PopupUngrabStrategy::All);
234	                return;
235	            }
236	            keyboard.set_focus(self, grab.current_grab(), serial);
237	            keyboard.set_grab(self, PopupKeyboardGrab::new(&grab), serial);
238	        }
239	        if let Some(pointer) = seat.get_pointer() {
240	            if pointer.is_grabbed()
241	                && !(pointer.has_grab(serial)
242	                    || pointer.has_grab(grab.previous_serial().unwrap_or_else(|| grab.serial())))
243	            {
244	                grab.ungrab(PopupUngrabStrategy::All);
245	                return;
246	            }
247	            pointer.set_grab(self, PopupPointerGrab::new(&grab), serial, Focus::Keep);
248	        }
249	    }
