297	fn check_grab(
298	    seat: &Seat<Fluxwm>,
299	    surface: &WlSurface,
300	    serial: Serial,
301	) -> Option<PointerGrabStartData<Fluxwm>> {
302	    let pointer = seat.get_pointer()?;
303	
304	    // Check that this surface has a click grab.
305	    if !pointer.has_grab(serial) {
306	        return None;
307	    }
308	
309	    let start_data = pointer.grab_start_data()?;
310	
311	    let (focus, _) = start_data.focus.as_ref()?;
312	    // If the focus was for a different surface, ignore the request.
313	    if !focus.id().same_client_as(&surface.id()) {
314	        return None;
315	    }
316	
317	    Some(start_data)
318	}
