320	/// Should be called on `WlSurface::commit`
321	pub fn handle_commit(state: &mut Fluxwm, surface: &WlSurface, just_unmapped: bool) {
322	    if let Some(id) = state.window_id(surface) {
323	        let initial = with_states(surface, |states| {
324	            states
325	                .data_map
326	                .get::<XdgToplevelSurfaceData>()
327	                .is_some_and(|data| !data.lock().unwrap().initial_configure_sent)
328	        });
329	        // A null-buffer unmap is not the initial bufferless commit of the
330	        // next mapping cycle. Wait for that subsequent commit before configuring.
331	        if initial
332	            && !just_unmapped
333	            && let Some(toplevel) = state
334	                .windows
335	                .get(id)
336	                .and_then(|item| item.window.toplevel())
337	        {
338	            crate::configure::clear_reply(toplevel);
339	            toplevel.send_configure();
340	        }
341	    }
342	    state.popups.commit(surface);
343	    if let Some(PopupKind::Xdg(xdg)) = state.popups.find_popup(surface)
344	        && !xdg.is_initial_configure_sent()
345	        && let Err(error) = xdg.send_configure()
346	    {
347	        tracing::debug!(%error, "popup configure rejected");
348	    }
349	}
