579	    pub fn relayout(&mut self) {
580	        // Capacity depends on the other members and viewport, not just the
581	        // rejected client's hints. Retry retained buffers on model changes so
582	        // a static client does not need to commit again after capacity returns.
583	        // One arena-order pass (at most the 1,024 owned roles), no timer or
584	        // recursive relayout. Recovery preserves the current selection.
585	        let pending: Vec<_> = self
586	            .windows
587	            .iter()
588	            .filter_map(|(id, item)| {
589	                (item.buffered
590	                    && !item.mapped
591	                    && item.admission_error.is_some()
592	                    && item.window.alive())
593	                .then_some(id)
594	            })
595	            .collect();
596	        let mut admitted = false;
597	        for id in pending {
598	            let surface = self
599	                .windows
600	                .get(id)
601	                .and_then(|item| item.window.toplevel())
602	                .expect("live rejected role in one dispatch")
603	                .wl_surface()
604	                .clone();
605	            if self
606	                .layout
607	                .insert_with_focus(id, self.constraints_for(&surface), false)
608	                .is_ok()
609	            {
610	                let maximize = self
611	                    .windows
612	                    .get(id)
613	                    .expect("live dispatch ID")
614	                    .initial_maximized;
615	                if self.layout.set_maximized(id, maximize).is_err() {
616	                    let _ = self.layout.remove(id);
617	                    continue;
618	                }
619	                let item = self.windows.get_mut(id).expect("live dispatch ID");
620	                item.mapped = true;
621	                item.admission_error = None;
622	                self.stats.maps += 1;
623	                self.bump_sequence();
624	                admitted = true;
625	                tracing::info!(%id, "window_admission_recovered");
626	            }
627	        }
628	        for placement in self.layout.placements() {
629	            let Some(item) = self.windows.get(placement.window) else {
630	                continue;
631	            };
632	            if !item.mapped {
633	                continue;
634	            }
635	            if let Some(toplevel) = item.window.toplevel() {
636	                toplevel.with_pending_state(|s| {
637	                    s.size = Some((placement.rect.width.round() as i32, placement.rect.height.round() as i32).into());
638	                    if self.layout.is_maximized(placement.window) {
639	                        s.states.set(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Maximized);
640	                    } else {
641	                        s.states.unset(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Maximized);
642	                    }
643	                    if self.layout.is_minimized(placement.window) {
644	                        s.states.set(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Suspended);
645	                    } else {
646	                        s.states.unset(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Suspended);
647	                    }
648	                    if placement.focused { s.states.set(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Activated); }
649	                    else { s.states.unset(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Activated); }
650	                });
651	                crate::configure::send_pending(toplevel);
652	            }
653	            if placement.visible {
654	                let rect = self.layout.camera().rect_to_view(placement.rect);
655	                self.space.map_element(
656	                    item.window.clone(),
657	                    (rect.x.round() as i32, rect.y.round() as i32),
658	                    placement.focused,
659	                );
660	            } else {
661	                if let Some(toplevel) = item.window.toplevel() {
662	                    Self::dismiss_root_popups(toplevel.wl_surface());
663	                }
664	                self.space.unmap_elem(&item.window);
665	            }
666	        }
667	        // Release seat wrappers only after all scene removals are authoritative;
668	        // cleanup repairs keyboard/pointer focus using the completed layout.
669	        self.cleanup_popup_grab();
670	        if admitted {
671	            self.restore_keyboard_focus();
672	        }
673	        self.request_redraw();
674	    }
